#!/usr/bin/env python3
"""Genera el HTML de la página 'Locales de Multiplaza' para lindsaymeneses.com.
La página carga los datos desde DATA_URL (JSON) y dibuja las tarjetas en el navegador."""
import sys, os
DATA_URL = sys.argv[1] if len(sys.argv) > 1 else "DATA_URL_PLACEHOLDER"
XLSX_URL = sys.argv[2] if len(sys.argv) > 2 else "XLSX_URL_PLACEHOLDER"
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
css = """.ml{--v:#0f3b2e;--v2:#0a241c;--o:#c9a45c;--o2:#ebd9ae;--c:#fbf6ec;--t:#1d1d1b;--g:#6b6b66;--l:#e7dfcf;font-family:Montserrat,system-ui,Segoe UI,Roboto,Arial,sans-serif;color:var(--t);background:var(--c);min-height:100vh;padding-bottom:64px;line-height:1.5}.ml *{box-sizing:border-box}.ml .in{max-width:1240px;margin:0 auto;padding:0 24px}.ml-hero{background:linear-gradient(135deg,var(--v2),var(--v));color:#fff;padding:56px 0 44px}.ml-hero .k{color:var(--o2);letter-spacing:.18em;text-transform:uppercase;font-size:12px;margin:0 0 10px}.ml-hero h1{font-size:clamp(28px,4vw,44px);margin:0 0 12px;line-height:1.15;color:#fff}.ml-hero p{margin:0;max-width:760px;color:#e8efe9}.ml-stats{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}.ml-stats div{background:rgba(255,255,255,.08);border:1px solid rgba(235,217,174,.35);border-radius:12px;padding:12px 16px;min-width:140px}.ml-stats b{display:block;font-size:26px;color:var(--o2)}.ml-stats span{font-size:11px;color:#d7e2da;text-transform:uppercase;letter-spacing:.08em}.ml-dl{display:inline-flex;align-items:center;gap:12px;margin-top:22px;background:var(--o2);color:var(--v2);text-decoration:none;padding:12px 18px;border-radius:12px;font-weight:600;border:1px solid var(--o)}.ml-dl:hover{background:#fff}.ml-dl svg{width:34px;height:34px;flex:none}.ml-dl small{display:block;font-weight:400;font-size:12px;color:#3d4b44}.ml-box{background:#fff;border:1px solid var(--l);border-radius:14px;padding:14px;display:flex;flex-wrap:wrap;gap:10px;margin:-22px 0 28px;position:relative;box-shadow:0 10px 30px rgba(10,36,28,.08)}.ml-tabs{display:flex;gap:6px}.ml-tabs button{border:1px solid var(--l);background:#fff;color:var(--v);padding:9px 14px;border-radius:999px;cursor:pointer;font:inherit;font-weight:600}.ml-tabs button[aria-pressed=true]{background:var(--v);color:#fff;border-color:var(--v)}.ml-box input,.ml-box select{font:inherit;padding:9px 12px;border:1px solid var(--l);border-radius:10px;background:#fff;color:var(--t);min-width:170px;flex:1}.ml-box label{display:flex;align-items:center;gap:6px;font-size:14px;color:var(--g)}.ml-mall h2{font-size:28px;margin:36px 0 8px;color:var(--v)}.ml-meta{margin:4px 0;font-size:14px;color:var(--g)}.ml-meta a{color:var(--v)}.ml-cnt{color:var(--v);font-weight:600;margin-bottom:16px}.ml-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:14px}.ml-card{background:#fff;border:1px solid var(--l);border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:8px}.ml-card:hover{box-shadow:0 8px 24px rgba(10,36,28,.1)}.ml-card header{display:flex;gap:12px;align-items:center}.ml-logo{width:72px;height:56px;flex:none;border:1px solid var(--l);border-radius:10px;background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden}.ml-logo img{max-width:64px;max-height:48px;object-fit:contain}.ml-logo span{font-weight:700;color:var(--v);font-size:18px}.ml-card h4{margin:0;font-size:17px;color:var(--v2);line-height:1.25}.ml-card h4 a{color:inherit;text-decoration:none}.ml-card h4 a:hover{text-decoration:underline}.ml-badge{display:inline-block;margin-top:4px;font-size:11px;background:var(--o2);color:var(--v2);padding:3px 8px;border-radius:999px;font-weight:600}.ml-desc{font-size:13px;color:var(--g);margin:0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.ml-desc.open{display:block}.ml-more{font-size:12px;color:var(--v);background:none;border:0;padding:0;cursor:pointer;text-align:left;font:inherit;font-size:12px;text-decoration:underline}.ml-f{display:grid;grid-template-columns:96px 1fr;gap:8px;font-size:13.5px;border-top:1px dashed var(--l);padding-top:6px}.ml-f span{color:var(--g)}.ml-f strong{font-weight:500;word-break:break-word}.ml-f a{color:var(--v)}.ml-f em{color:#b08a3c;font-style:normal;font-size:12.5px}.ml-ger .ml-f{background:#fff8e1;border-radius:8px;padding:6px 8px;border-top:0}.ml-soc{display:flex;flex-wrap:wrap;gap:6px}.ml-soc a{font-size:12px;border:1px solid var(--l);border-radius:999px;padding:3px 10px;color:var(--v);text-decoration:none;background:#fff}.ml-soc a:hover{background:var(--o2)}.ml-card footer{display:flex;justify-content:space-between;gap:8px;font-size:11.5px;color:var(--g);margin-top:auto;padding-top:6px}.ml-card footer a{color:var(--v)}.ml-ok{color:#2e7d4f;font-weight:600}.ml-pd{color:#b08a3c;font-weight:600}.ml-hide{display:none!important}.ml-empty{text-align:center;color:var(--g);padding:40px 0}.ml-note{font-size:13px;color:var(--g);margin-top:40px}.ml-note a{color:var(--v)}@media(max-width:640px){.ml-f{grid-template-columns:1fr}.ml-box{margin-top:-10px}}"""
js = """(function(){var w=document.getElementById('locales-multiplaza'),tab='todos',D=null;
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function f(l,v,link){if(!v)return'<div class="ml-f"><span>'+l+'</span><em>Por completar</em></div>';var t=link?'<a href="'+esc(v)+'" target="_blank" rel="noopener">'+esc(v.replace(/^https?:\\/\\//,'').replace(/\\/$/,''))+'</a>':esc(v);return'<div class="ml-f"><span>'+l+'</span><strong>'+t+'</strong></div>'}
function tel(v){if(!v)return f('Teléfono','');return'<div class="ml-f"><span>Teléfono</span><strong>'+v.split(' / ').map(function(x){return'<a href="tel:+506'+x.replace(/\\D/g,'')+'">'+esc(x)+'</a>'}).join(' / ')+'</strong></div>'}
function mail(v){if(!v)return f('Correo','');return'<div class="ml-f"><span>Correo</span><strong>'+v.split(', ').map(function(x){return'<a href="mailto:'+esc(x)+'">'+esc(x)+'</a>'}).join(', ')+'</strong></div>'}
function soc(r){var a=[];if(r.facebook)a.push(['Facebook',r.facebook]);if(r.instagram)a.push(['Instagram',r.instagram]);if(r.tiktok)a.push(['TikTok',r.tiktok]);if(r.whatsapp)a.push(['WhatsApp',r.whatsapp]);if(r.web)a.push(['Sitio web',r.web]);if(!a.length)return'<div class="ml-f"><span>Redes</span><em>Por completar</em></div>';return'<div class="ml-f"><span>Redes</span><strong class="ml-soc">'+a.map(function(x){return'<a href="'+esc(x[1])+'" target="_blank" rel="noopener">'+x[0]+'</a>'}).join('')+'</strong></div>'}
function ini(n){return esc(n.replace(/[^A-Za-zÁÉÍÓÚÑáéíóúñ0-9 ]/g,'').split(' ').filter(Boolean).slice(0,2).map(function(x){return x[0]}).join('').toUpperCase()||'?')}
var MALLS={escazu:{nombre:'Multiplaza Escazú',direccion:'Autopista Próspero Fernández, San Rafael de Escazú, San José',telefono:'+506 2201-6025',horario:'L-S 10:00 a.m.–9:00 p.m. · D 10:00 a.m.–8:00 p.m.',web:'https://multiplaza.com/escazu'},curridabat:{nombre:'Multiplaza Curridabat',direccion:'Frente al Registro Nacional, Curridabat, San José',telefono:'4001-7999 · multiplaza.curridabat@gruporoble.com',horario:'L-S 10:00 a.m.–9:00 p.m. · D 10:00 a.m.–8:00 p.m.',web:'https://multiplaza.com/curridabat'}};
function parse(txt){var L=txt.split(/\\r?\\n/).filter(function(x){return x.length}),gen='',i=0;if(L[0].charAt(0)==='#'){gen=L[0].split('\\t')[1]||'';i=1}var F=L[i].split('\\t'),rows=[];for(i=i+1;i<L.length;i++){var a=L[i].split('\\t'),o={};F.forEach(function(k,j){o[k]=a[j]||''});rows.push(o)}var cats=[];rows.forEach(function(r){if(r.categoria&&cats.indexOf(r.categoria)<0)cats.push(r.categoria)});cats.sort(function(a,b){return a.localeCompare(b,'es')});return{generado:gen,malls:MALLS,cats:cats,rows:rows}}
function render(){var rows=D.rows;
var sel=w.querySelector('#ml-cat');D.cats.forEach(function(c){var o=document.createElement('option');o.value=c;o.textContent=c;sel.appendChild(o)});
w.querySelector('#ml-n-total').textContent=rows.length;w.querySelector('#ml-n-e').textContent=rows.filter(function(r){return r.mall==='escazu'}).length;w.querySelector('#ml-n-c').textContent=rows.filter(function(r){return r.mall==='curridabat'}).length;w.querySelector('#ml-n-cat').textContent=D.cats.length;w.querySelector('#ml-n-tel').textContent=rows.filter(function(r){return r.telefono}).length;
Object.keys(D.malls).forEach(function(k){var m=D.malls[k],rs=rows.filter(function(r){return r.mall===k}),t=rs.filter(function(r){return r.tipo==='T'}).length;
var h='<h2>'+esc(m.nombre)+'</h2><p class="ml-meta"><strong>Dirección:</strong> '+esc(m.direccion)+' · <strong>Teléfono:</strong> '+esc(m.telefono)+' · <strong>Horario:</strong> '+esc(m.horario)+'</p><p class="ml-meta"><strong>Sitio:</strong> <a href="'+m.web+'" target="_blank" rel="noopener">'+m.web.replace('https://','')+'</a> · <strong>Directorio oficial:</strong> <a href="'+m.web+'/tiendas" target="_blank" rel="noopener">tiendas</a> / <a href="'+m.web+'/restaurantes" target="_blank" rel="noopener">restaurantes</a> · <strong>Redes Multiplaza CR:</strong> <a href="https://www.facebook.com/MultiplazaCostaRica" target="_blank" rel="noopener">Facebook</a> · <a href="https://www.instagram.com/multiplazacr" target="_blank" rel="noopener">Instagram</a></p><p class="ml-meta ml-cnt">'+rs.length+' locales: '+t+' tiendas y servicios, '+(rs.length-t)+' restaurantes.</p><div class="ml-grid">';
rs.forEach(function(r){var p=['telefono','correo','gerente'].filter(function(k){return!r[k]}).length+((r.facebook||r.instagram||r.tiktok||r.web)?0:1);
var logo=r.logo?'<img src="'+esc(r.logo)+'" alt="'+esc(r.nombre)+'" loading="lazy" onerror="this.parentNode.innerHTML=\\'<span>'+ini(r.nombre)+'</span>\\'">':'<span>'+ini(r.nombre)+'</span>';
h+='<article class="ml-card" data-mall="'+k+'" data-cat="'+esc(r.categoria)+'" data-tipo="'+r.tipo+'" data-pend="'+p+'" data-q="'+esc((r.nombre+' '+r.categoria+' '+r.ubicacion+' '+r.descripcion).toLowerCase())+'"><header><div class="ml-logo">'+logo+'</div><div><h4><a href="'+esc(r.url)+'" target="_blank" rel="noopener">'+esc(r.nombre)+'</a></h4><span class="ml-badge">'+esc(r.categoria)+'</span></div></header>'+(r.descripcion?'<p class="ml-desc">'+esc(r.descripcion)+'</p><button type="button" class="ml-more">Leer más</button>':'')+'<div class="ml-f"><span>Ubicación</span><strong>'+(r.ubicacion?esc(r.ubicacion):'<em>No indicada</em>')+'</strong></div>'+f('Horario',r.horario)+tel(r.telefono)+mail(r.correo)+soc(r)+'<div class="ml-ger">'+f('Gerente',r.gerente)+f('Contacto gerente',r.contacto_gerente)+'</div><footer><a href="'+esc(r.url)+'" target="_blank" rel="noopener">Ficha oficial en multiplaza.com</a><span class="'+(p?'ml-pd':'ml-ok')+'">'+(p?p+(p>1?' datos':' dato')+' por completar':'Datos completos')+'</span></footer></article>'});
w.querySelector('#ml-'+k).innerHTML=h+'</div>'});
w.querySelectorAll('.ml-more').forEach(function(b){b.addEventListener('click',function(){var d=b.previousElementSibling;d.classList.toggle('open');b.textContent=d.classList.contains('open')?'Leer menos':'Leer más'})});
var cards=[].slice.call(w.querySelectorAll('.ml-card')),secs=[].slice.call(w.querySelectorAll('.ml-mall')),q=w.querySelector('#ml-q'),cat=w.querySelector('#ml-cat'),tipo=w.querySelector('#ml-tipo'),pend=w.querySelector('#ml-pend'),vac=w.querySelector('#ml-vacio');
function n(s){return(s||'').toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'')}
function run(){var qq=n(q.value.trim()),c=cat.value,t=tipo.value,p=pend.checked,vis=0,pm={escazu:0,curridabat:0};cards.forEach(function(el){var ok=(tab==='todos'||el.dataset.mall===tab)&&(!c||el.dataset.cat===c)&&(!t||el.dataset.tipo===t)&&(!p||el.dataset.pend!=='0')&&(!qq||n(el.dataset.q).indexOf(qq)>-1);el.classList.toggle('ml-hide',!ok);if(ok){vis++;pm[el.dataset.mall]++}});secs.forEach(function(s){s.classList.toggle('ml-hide',(tab!=='todos'&&s.id!=='ml-'+tab)||pm[s.id.slice(3)]===0)});vac.classList.toggle('ml-hide',vis>0)}
w.querySelectorAll('.ml-tabs button').forEach(function(b){b.addEventListener('click',function(){tab=b.dataset.tab;w.querySelectorAll('.ml-tabs button').forEach(function(x){x.setAttribute('aria-pressed',x===b?'true':'false')});run()})});[q,cat,tipo,pend].forEach(function(el){el.addEventListener('input',run);el.addEventListener('change',run)});
w.querySelector('#ml-gen').textContent=D.generado}
fetch(w.dataset.src,{cache:'no-cache'}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.text()}).then(function(t){D=parse(t);render()}).catch(function(e){w.querySelector('#ml-escazu').innerHTML='<p class="ml-empty">No se pudieron cargar los datos ('+esc(e.message)+'). Recargue la página.</p>'});})();"""
page = f"""<!-- wp:html -->
<div class="ml" id="locales-multiplaza" data-src="{DATA_URL}">
<style>{css}</style>
<div class="ml-hero"><div class="in"><p class="k">Directorio de trabajo · Multiplaza Costa Rica</p><h1>Locales de Multiplaza Escazú y Curridabat</h1><p>Todos los locales del directorio oficial de Grupo Roble, con logo, categoría, ubicación, horario, teléfono, correo y redes sociales de cada uno, más un espacio para registrar al gerente de cada local. Datos extraídos de multiplaza.com el <span id="ml-gen">…</span>.</p>
<div class="ml-stats"><div><b id="ml-n-total">…</b><span>Locales</span></div><div><b id="ml-n-e">…</b><span>Escazú</span></div><div><b id="ml-n-c">…</b><span>Curridabat</span></div><div><b id="ml-n-cat">…</b><span>Categorías</span></div><div><b id="ml-n-tel">…</b><span>Con teléfono</span></div></div>
<a class="ml-dl" href="{XLSX_URL}" download><svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#1D6F42" d="M28 4H12a3 3 0 0 0-3 3v34a3 3 0 0 0 3 3h26a3 3 0 0 0 3-3V15Z"/><path fill="#0B5A30" d="M28 4v11h11Z"/><rect x="4" y="18" width="24" height="18" rx="2" fill="#107C41"/><text x="16" y="31.5" text-anchor="middle" font-family="Arial,sans-serif" font-weight="700" font-size="13" fill="#fff">X</text><path fill="#fff" opacity=".9" d="M31 22h6v2h-6zM31 26h6v2h-6zM31 30h6v2h-6z"/></svg><span><strong>Descargar lista en Excel</strong><small>2 hojas: Escazú y Curridabat · logo y datos de cada local · columna Gerente para completar</small></span></a></div></div>
<div class="in"><div class="ml-box"><div class="ml-tabs" role="group" aria-label="Centro comercial"><button type="button" data-tab="todos" aria-pressed="true">Ambos malls</button><button type="button" data-tab="escazu" aria-pressed="false">Escazú</button><button type="button" data-tab="curridabat" aria-pressed="false">Curridabat</button></div><input type="search" id="ml-q" placeholder="Buscar local, categoría, ubicación…" aria-label="Buscar"><select id="ml-cat" aria-label="Categoría"><option value="">Todas las categorías</option></select><select id="ml-tipo" aria-label="Tipo"><option value="">Tiendas y restaurantes</option><option value="T">Solo tiendas y servicios</option><option value="R">Solo restaurantes</option></select><label><input type="checkbox" id="ml-pend"> Solo con datos por completar</label></div>
<section class="ml-mall" id="ml-escazu"><noscript><p>Active JavaScript para ver el directorio.</p></noscript></section>
<section class="ml-mall" id="ml-curridabat"></section>
<p class="ml-empty ml-hide" id="ml-vacio">Ningún local coincide con el filtro.</p>
<div class="ml-note"><p><strong>Fuente:</strong> directorio oficial de <a href="https://multiplaza.com/escazu/tiendas" target="_blank" rel="noopener">Multiplaza Escazú</a> y <a href="https://multiplaza.com/curridabat/tiendas" target="_blank" rel="noopener">Multiplaza Curridabat</a> (Grupo Roble). Logos, descripciones, ubicaciones, horarios y contactos se toman de la ficha de cada local en multiplaza.com; el nombre del local enlaza a esa ficha. Los campos <em>Gerente</em> y <em>Contacto gerente</em>, y los datos que el directorio no publica, están marcados <em>Por completar</em>.</p></div></div>
<script>{js}</script>
</div>
<!-- /wp:html -->"""
open(f"{ROOT}/documentos/pagina-locales-multiplaza.html", "w", encoding="utf-8").write(page)
print(len(page))
